import{_ as o,l as r,o as e,c as s,v as i,p as n,x as t,d as A,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"AIMS 掩模鉴定","description":"","frontmatter":{"title":"AIMS 掩模鉴定","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/aims-mask-qualification.md","filePath":"litho/aims-mask-qualification.md","lastUpdated":1789023840000}'),p={name:"litho/aims-mask-qualification.md"};function E(S,a,m,c,M,I){const l=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="aims-掩模鉴定" tabindex="-1">AIMS 掩模鉴定 <a class="header-anchor" href="#aims-掩模鉴定" aria-label="Permalink to &quot;AIMS 掩模鉴定&quot;">​</a></h1><div class="epigraph"><p>SEM 看见的是吸收体形貌；AIMS 看见的是扫描机波长与照明下的空中像——修过的补丁只在这里才算印不印。</p><footer>—— 对照 Zeiss AIMS（Aerial Image Measurement System）掩模鉴定的公开产品与文献通称</footer></div><p><a href="/litho/pellicle-mount-inspect">上一课</a>给出装膜后的出货态。缺口是光学检验与 SEM 都不等于扫描机打印。本课钉 AIMS。鉴定通过的版在寿命里仍可能雾化，留给[下一课](/litho/mask-haze）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>掩模厂 D2DB 用的检验波长、NA、照明往往不是晶圆扫描机那一套。缺陷或修复补丁在非光化图上「合格」，在 193 nm 或 13.5 nm 的部分相干空中像上仍可能桥、断、CD 飞。AIMS 用等效的波长/NA/照明（DUV 成熟；EUV 光化 AIMS 更稀缺、更贵）在掩模上直接量空中像，把缺陷放到工艺窗口语言里。</p><p>缺口是<strong>打印函数</strong>，不是再提高检验像素。把 AIMS 当「更高分辨率 SEM」，仪器目的就错了。</p><h3 id="与严格电磁的分工" tabindex="-1">与严格电磁的分工 <a class="header-anchor" href="#与严格电磁的分工" aria-label="Permalink to &quot;与严格电磁的分工&quot;">​</a></h3><p><a href="/litho/fdtd-mask">FDTD/RCWA</a> 后课会算掩模 3D；AIMS 是实物测量，吃真实侧壁、真实修复材料、真实 pellicle。模型再好也替代不了补丁的未知折射率。量产用 AIMS 抽关键缺陷，不用它扫整版——产能不允许。</p><p><span class="marginnote">EUV AIMS 与 DUV AIMS 不是同一台合同。无光化工具时，只能用模型 + 非光化再加风险接受，不能假装已经打印鉴定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程：检验列出候选 → AIMS 在剂量/焦点小矩阵上看空中像 CD 或强度切片 → 判打印/不打印/可放行。照明必须尽量匹配 SMO 冻结的光瞳，否则鉴定的是另一台扫描机。pellicle 若已装，光路含膜；拆膜鉴定再装，状态不一致。</p><p>与 MPC：系统 3D 边应由模型校准，AIMS 主抓局部异常，而不是给全场 OPC 重新拟合。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>AIMS 物镜收集掩模衍射，重建的是与扫描机共轭的空中像平面强度（及部分相位信息，视系统而定）。缺陷的打印取决于它是否把通带内的衍射级搬出窗口。SEM 看到的体积缺陷若频谱在通带外，AIMS 可能判不打印——这正是 nuisance 过滤的物理。</p>',14)),(e(),n(h,null,{default:t(()=>[d(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20CAND%5B%22%E6%A3%80%E9%AA%8C%E5%80%99%E9%80%89%E7%BC%BA%E9%99%B7%22%5D%20--%3E%20AIMS%5B%22%E6%89%AB%E6%8F%8F%E6%9C%BA%E7%AD%89%E4%BB%B7%E7%A9%BA%E4%B8%AD%E5%83%8F%22%5D%0A%20%20PUP%5B%22%E5%8C%B9%E9%85%8D%E5%85%89%E7%9E%B3%20%2F%20NA%20%2F%20%CE%BB%22%5D%20--%3E%20AIMS%0A%20%20AIMS%20--%3E%20PR%5B%22%E6%89%93%E5%8D%B0%20%2F%20%E4%B8%8D%E6%89%93%E5%8D%B0%22%5D%0A%20%20PR%20--%3E%20SHIP%5B%22%E6%94%BE%E8%A1%8C%20%E6%8A%A5%E5%BA%9F%20%E5%86%8D%E4%BF%AE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>AIMS 不测量晶圆胶随机，不替代套刻。抽检不能证明未抽到的缺陷无害。不编造某缺陷尺寸的打印阈值表。</p><p>后课默认：出货前关键缺陷已经用打印视角判过；下一课处理上机之后随曝光剂量慢慢长出来的雾。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>AIMS 用扫描机光学条件量空中像，鉴定缺陷与修复是否打印。</li><li>非光化检验通过 ≠ AIMS 合格；光瞳必须匹配。</li><li>整版扫 AIMS 不可行，只抽候选。</li><li>出处：Zeiss AIMS 公开论述；SPIE 掩模光化鉴定文献。</li></ul>',5))])}const B=o(p,[["render",E]]);export{u as __pageData,B as default};
